import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Assets — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Assets — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/assets"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Assets — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/assets"}]]},"headers":[],"relativePath":"user-guide/assets.md","filePath":"user-guide/assets.md","lastUpdated":1787850471000}'),r={name:"user-guide/assets.md"};function n(i,e,l,d,c,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="assets-—-user-guide" tabindex="-1">Assets — User Guide <a class="header-anchor" href="#assets-—-user-guide" aria-label="Permalink to &quot;Assets — User Guide&quot;">​</a></h1><h2 id="who-can-use-assets" tabindex="-1">Who can use Assets <a class="header-anchor" href="#who-can-use-assets" aria-label="Permalink to &quot;Who can use Assets&quot;">​</a></h2><p>Your workspace must have the <strong>Assets</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see assets assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Assets</strong> from the sidebar (Operations area).</p><ul><li>Search by name, number, serial number, manufacturer, model, or location</li><li>Filter by status, category, and assignee, or toggle <strong>My Assets</strong></li><li>KPI cards summarize total, my assets, unassigned, and counts by status</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted asset from the row menu</li><li><strong>Delete permanently</strong> requires <code>assets.force.delete</code> (same posture as Vendors — not on default role maps)</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New asset</strong> (shortcut: <code>n</code> when the list is focused and you have create permission)</li><li>Enter name (required). Optionally set status, category, manufacturer, model, serial number, location, purchase details, warranty end, assignee, and — when those modules are installed — vendor or employee custodian</li><li>Save — EloSync assigns the next asset number (<code>AST-00001</code>, …)</li></ol><p>Edit from the row menu or the asset page. Focus search with <code>Ctrl/⌘+F</code>.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the workspace assignee from the asset page or the create/edit form.</p><p>Assignees must be <strong>eligible custodians</strong>: active non-owner users who are not flagged <strong>Exclude from lead assignment</strong>. Workspace owners can still hold assets when they create them (default assignee = creator), but you cannot re-assign an asset <em>to</em> the owner through the assign picker. Clear assignee with <strong>Unassigned</strong>.</p><h2 id="vendor-employee-links" tabindex="-1">Vendor &amp; employee links <a class="header-anchor" href="#vendor-employee-links" aria-label="Permalink to &quot;Vendor &amp; employee links&quot;">​</a></h2><ul><li><strong>Vendor</strong> appears only when the Vendors module is installed</li><li><strong>Employee</strong> (custodian) appears only when the Employees module is installed</li></ul><p>These are optional context links — Assets works without either module.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the asset</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Active</td><td>In normal use</td></tr><tr><td>In repair</td><td>Temporarily unavailable</td></tr><tr><td>Retired</td><td>No longer in active use</td></tr><tr><td>Disposed</td><td>Written off / removed</td></tr></tbody></table>',20)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
